UPDATE `StaffProfile`
SET `bio` = 'An agricultural professional, agribusiness consultant and development practitioner. He holds a BSc in Agriculture and is pursuing a MA in Project Planning and Management from the University of Nairobi.\n\nHe has 13 years of professional experience, including seven years in government service and six years with non-governmental organizations, specializing in programme management, agricultural development and community empowerment.\n\nCurrently a full-time agribusiness consultant and farmer, he leads farmer empowerment and agricultural commercialization initiatives in Ganze Sub-County, with a focus on cashew farming, value addition and rural livelihoods.\n\nAs Chairman of the Board of Governors, he brings his experience in strategic leadership and community development to support Godoma TTI’s growth and its ambition to become a center of excellence in technical training, research and business incubation.'
WHERE `group` = 'BOARD' AND `name` = 'Emmanuel Masha';
